DECLARE
  i PLS_INTEGER := 0;
BEGIN
  LOOP
    i := i + 1;
    EXIT WHEN i >= 3;
  END LOOP;
END;

DECLARE
  i PLS_INTEGER := 0;
BEGIN
  WHILE i < 3 LOOP
    i := i + 1;
  END LOOP;
END;

